const OPS_NOT_IMPLEMENTED_ACTION_SET: ReadonlySet<string> = new Set<string>(OPS_NOT_IMPLEMENTED_ACTIONS)

export function isOpsNotImplementedAction(value: unknown): value is (typeof OPS_NOT_IMPLEMENTED_ACTIONS)[number] {
  return typeof value === "string" && OPS_NOT_IMPLEMENTED_ACTION_SET.has(value)
}

/**
 * Server-side hook for errors caught by the POST handler's catch-all. The response
 * body is (or will be) sanitised, so tests spy on `onError` to detect programming
 * errors (TypeError / ReferenceError) independently of the response text.
 */
export const opsReportingDiagnostics = {
  onError(err: unknown): void {
    console.error("[ops-reporting] POST action failed", err)
  },
}
